#include <stdio.h>
int main(void) {
    double cpi = 1.25;
    double ipc = 1.0 / cpi;
    double f = 4e9;
    double mips = f / (cpi * 1e6);
    printf("CPI = 1.25\n");
    printf("IPC = 1 / CPI = %.2f 条/周期\n", ipc);
    printf("主频 = 4.0 GHz\n");
    printf("等效 MIPS = 4e9 / (1.25 * 1e6) = %.0f\n", mips);
    return 0;
}
